select count(1)
from error_types
where deleted = false

  and type_level = #{request.typeLevel}


  and parent_id = #{request.parentId}


  and enabled = #{request.enabled}

select id, parent_id, type_level, code, name, description, name_en, description_en, sort_order, enabled, deleted, created_at, updated_at from error_types where deleted = false
and type_level = #{request.typeLevel}
and parent_id = #{request.parentId}
and enabled = #{request.enabled}
order by type_level asc, parent_id nulls first, sort_order asc, id asc limit #{limit} offset #{offset}
